/** Raw SVG path data starts with a move command — that is how a path is told from a registry name. */
const PATH_RE = /^[Mm][\s\d.,-]/

/**
 * Merges extra glyphs into the registry (a plugin calls this through `CoreUI.kit.registerIcons`).
 * Entries whose value is not a non-empty string are ignored; existing names are overwritten.
 *
 * @param {Record<string, string>} map name -> 24 x 24 SVG path data
 * @returns {string[]} the names that were actually added
 */
export function registerIcons(map) {
  const added = []
  if (!map || typeof map !== 'object') return added
  for (const name of Object.keys(map)) {
    const d = map[name]
    if (typeof d !== 'string' || d === '') continue
    ICONS[name] = d
    added.push(name)
  }
  return added
}

/**
 * Resolves whatever an `icon` prop was given: a registry name, or raw path data passed through.
 *
 * @param {string} nameOrPath registry name (`'map-marker'`) or 24 x 24 path data (`'M12 2 ...'`)
 * @returns {string} the path data, or `''` when the name is unknown
 */
export function iconPath(nameOrPath) {
  if (typeof nameOrPath !== 'string' || nameOrPath === '') return ''
  const known = ICONS[nameOrPath]
  if (typeof known === 'string') return known
  return PATH_RE.test(nameOrPath) ? nameOrPath : ''
}
